import re


def encode(text):
    """Run-length encode text that holds no digits. See TASK.md."""
    for ch in text:
        if ch.isdigit():
            raise ValueError("text must not contain digits")
    out = []
    i = 0
    n = len(text)
    while i < n:
        j = i
        while j < n and text[j] == text[i]:
            j += 1
        run = j - i
        if run == 1:
            out.append(text[i])
        else:
            out.append(str(run) + text[i])
        i = j
    return "".join(out)


def decode(text):
    """Reverse `encode`. See TASK.md."""
    out = []
    i = 0
    n = len(text)
    while i < n:
        if text[i].isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            count_str = text[i:j]
            if len(count_str) > 1 and count_str[0] == "0":
                raise ValueError("count with leading zero: " + count_str)
            count = int(count_str)
            if count <= 1:
                raise ValueError("count must be at least 2: " + count_str)
            if j >= n:
                raise ValueError("count with no character after it: " + count_str)
            out.append(text[j] * count)
            i = j + 1
        else:
            out.append(text[i])
            i += 1
    return "".join(out)
